function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1) return 'grid needs at least one row.';
  const m = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (m < 1) return 'Each row needs at least one value.';
  if (!grid.every(row => Array.isArray(row) && row.length === m)) return 'All rows must have the same length.';
  if (grid.length * m < 2 || grid.length * m > 100000) return 'grid holds 2 to 10^5 cells.';
  if (!grid.every(row => row.every(v => Number.isInteger(v) && v >= 1 && v <= 1e9))) return 'Each value is an integer from 1 to 10^9.';
  return null;
}

