function constructProductMatrix(grid) {
  const cells = grid.flat();
  const out = cells.map((_, skip) => {
    let product = 1;
    for (let k = 0; k < cells.length; k++) if (k !== skip) product = (product * cells[k]) % 12345;
    return product;
  });
  const width = grid[0].length;
  return grid.map((_, r) => out.slice(r * width, (r + 1) * width));
}

