function generate(rand, size) {
  const value = () => {
    const pick = rand();
    if (pick < 0.08) return 12345 * (1 + Math.floor(rand() * 5));
    if (pick < 0.16) return [3, 5, 823, 15, 2469, 4115][Math.floor(rand() * 6)];
    if (pick < 0.3) return 1;
    if (pick < 0.4) return 1e9 - Math.floor(rand() * 3);
    return size === 'large' ? 1 + Math.floor(rand() * 1e9) : 1 + Math.floor(rand() * 30);
  };
  let rows, cols;
  if (size === 'large') {
    const shape = rand();
    if (shape < 0.5) { rows = 100; cols = 100; }
    else if (shape < 0.75) { rows = 1; cols = 2000; }
    else { rows = 2000; cols = 1; }
  } else {
    do {
      rows = 1 + Math.floor(rand() * 4);
      cols = 1 + Math.floor(rand() * 4);
    } while (rows * cols < 2);
  }
  return [Array.from({ length: rows }, () => Array.from({ length: cols }, value))];
}
